	private static function validate_enum( $value, $allowed ) {
		if ( $value === null || $value === '' ) {
			return null;
		}
		$v = sanitize_text_field( (string) $value );
		return in_array( $v, $allowed, true ) ? $v : null;
	}

	/**
	 * DOMENO metodas: sukuria augintini ir grazina GRYNA rezultata.
	 *
	 * S333 (Commit 1) — TIK ATSKYRIMAS, JOKIO ELGSENOS PAKEITIMO.
	 * Anksciau `create_pet()` grazindavo `WP_REST_Response` / `rest_ensure_response`,
	 * t.y. domeno metodas kalbejo HTTP kalba. Del to jo negalejo kviesti
	 * neHTTP kelias (magic-link claim, S328 anoniminio drafto perkelimas).
	 *
	 * SIAME COMMIT'E NEKEICIAMA: validacija, client_ref semantika (per-user),
	 * UNIQUE, draftu integracija, mirror_to_sender(), eventu logika.
	 * `create_pet()` lieka suderinamumo wrapper'iu su IDENTISKU HTTP atsakymu.
	 *
	 * @return array|WP_Error
	 *   ['status'=>'deduplicated',         'pet_id'=>int, 'pet'=>array]
	 *   ['status'=>'duplicate_candidate',  'candidates'=>array]
	 *   ['status'=>'created',              'pet_id'=>int, 'is_primary'=>bool, 'pet'=>array]
	 *   WP_Error('create_failed')
	 */
	public static function create_pet_result( $user_id, $input, $client_ref = null, $force_new = false ) {
		global $wpdb;
		$now = gmdate( 'Y-m-d H:i:s' );

		// Idempotentiskumas: jei toks client_ref jau perkeltas siam vartotojui -> grazinam esama
		// (pakartotinis magic link paspaudimas nekuria dublikato).
		if ( $client_ref ) {
			$existing_id = (int) $wpdb->get_var( $wpdb->prepare(
				"SELECT id FROM `" . self::table_name() . "` WHERE user_id = %d AND client_ref = %s AND status='active' LIMIT 1",
				$user_id, $client_ref
			) );
			if ( $existing_id ) {
				return array(
					'status' => 'deduplicated',
					'pet_id' => $existing_id,
					'pet'    => self::get_pet( $existing_id ),
				);
			}
		}

		// S206: semantinis dublikatas. client_ref apsaugo tik nuo TO PATIES juodrascio —
		// tas pats augintinis is kito irenginio turi klausti vartotojo, ne atsirasti tyliai.
		if ( ! $force_new && ! empty( $input['pet_name'] ) ) {
			$candidates = self::find_duplicate_candidates(
				$user_id,
				$input['pet_name'],
				isset( $input['species'] ) ? $input['species'] : null
			);
			if ( ! empty( $candidates ) ) {
				return array(
					'status'     => 'duplicate_candidate',
					'candidates' => $candidates,
				);
			}
		}

		$existing_count = (int) $wpdb->get_var( $wpdb->prepare(
			"SELECT COUNT(*) FROM `" . self::table_name() . "` WHERE user_id = %d AND status='active'",
			$user_id
		) );
		$is_primary = ( $existing_count === 0 ) ? 1 : 0;

		$data = array_merge( array(
			'user_id'    => $user_id,
			'is_primary' => $is_primary,
			'status'     => 'active',
			'client_ref' => $client_ref,
			'created_at' => $now,
			'updated_at' => $now,
		), $input );

		$wpdb->insert( self::table_name(), $data );
		$pet_id = (int) $wpdb->insert_id;

		if ( ! $pet_id ) {
			return new WP_Error( 'create_failed', 'Nepavyko išsaugoti anketos.', array( 'status' => 500 ) );
		}

		// S205: upsert PIRMA, event'as PO — subscriber turi egzistuoti pries atkeliaujant event'ui.
		if ( $is_primary ) {
			self::mirror_to_sender( $user_id, $pet_id );
		}
		self::emit_created( $user_id, $pet_id, $input );

		return array(
			'status'     => 'created',
			'pet_id'     => $pet_id,
			'is_primary' => (bool) $is_primary,
			'pet'        => self::get_pet( $pet_id ),
		);
	}

	/**
	 * SUDERINAMUMO WRAPPER — HTTP atsakymo formavimas.
	 *
	 * S333: islaiko TIKSLIAI ta pati HTTP statusa ir response JSON kaip iki
	 * refaktoringo (baseline commit 6763d670). `handle_save()` NELIECIAMAS.
	 * Draftu claim grandine (S328) kvies `create_pet_result()`, NE si metoda.
	 */

