private static function create_pet( $user_id, $input, $client_ref = null, $force_new = false ) {
		$rez = self::create_pet_result( $user_id, $input, $client_ref, $force_new );

		if ( is_wp_error( $rez ) ) {
			return $rez;
		}

		if ( 'deduplicated' === $rez['status'] ) {
			return rest_ensure_response( array(
				'ok'          => true,
				'pet_id'      => $rez['pet_id'],
				'deduplicated'=> true,
				'pet'         => $rez['pet'],
			) );
		}

		if ( 'duplicate_candidate' === $rez['status'] ) {
			return new WP_REST_Response( array(
				'ok'                   => false,
				'code'                 => 'duplicate_candidate',
				'message'              => 'Rastas galimas dublikatas — reikia vartotojo sprendimo.',
				'duplicate_candidates' => $rez['candidates'],
			), 409 );
		}

		return rest_ensure_response( array(
			'ok'         => true,
			'pet_id'     => $rez['pet_id'],
			'is_primary' => $rez['is_primary'],
			'pet'        => $rez['pet'],
		) );
	}

	private static function update_pet( $user_id, $pet_id, $input ) {
		global $wpdb;

		$pet = $wpdb->get_row( $wpdb->prepare(
			"SELECT * FROM `" . self::table_name() . "` WHERE id = %d AND user_id = %d AND status!='deleted'",
			$pet_id, $user_id
		) );
		if ( ! $pet ) {
			return new WP_Error( 'not_found', 'Augintinis nerastas.', array( 'status' => 404 ) );
		}

		$changed = array();
		$updates = array();
		foreach ( $input as $f => $val ) {
			if ( property_exists( $pet, $f ) && $val !== $pet->$f ) {
				$changed[] = $f;
				$updates[ $f ] = $val;
			}
		}

		if ( empty( $updates ) ) {
			return rest_ensure_response( array( 'ok' => true, 'pet_id' => $pet_id, 'unchanged' => true, 'pet' => self::get_pet( $pet_id ) ) );
		}

		$updates['updated_at'] = gmdate( 'Y-m-d H:i:s' );
		$wpdb->update( self::table_name(), $updates, array( 'id' => $pet_id ) );

		// S205: upsert PIRMA, event'as PO (ta pati logika kaip create kelyje).
		if ( (int) $pet->is_primary === 1 ) {
			self::mirror_to_sender( $user_id, $pet_id );
		}
		self::emit_updated( $user_id, $pet_id, $changed );

		return rest_ensure_response( array(
			'ok'             => true,
			'pet_id'         => $pet_id,
			'changed_fields' => $changed,
			'pet'            => self::get_pet( $pet_id ),
		) );
	}
